/*
 * Apple Wallet pass images (icon + logo, @1x/@2x/@3x), base64-embedded so they are
 * bundled into the serverless function (a bare fs read of public/ is not reliably
 * traced onto Vercel lambdas). Regenerate from public/favicon.png + public/cmba-logo-sm.png
 * with scripts/gen-apple-pass-assets (see the member-cards docs). A .pkpass MUST contain
 * at least icon.png or Wallet rejects it.
 */
const RAW: Record<string, string> = {
  "icon.png": "",
  "icon@2x.png": "",
  "icon@3x.png": "",
  "logo.png": "",
  "logo@2x.png": "",
  "logo@3x.png": "",
}

/** Decoded pass image buffers, keyed by their in-bundle filename. */
export const APPLE_PASS_IMAGES: Record<string, Buffer> = Object.fromEntries(
  Object.entries(RAW).map(([name, b64]) => [name, Buffer.from(b64, "base64")]),
)
